query:
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?expert a pv:SensorExpert ;
           rdfs:label ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?lcd prodi:supplier ?supplier ;
        pv:hasType "LCD" .
  ?supplier rdfs:locatedIn ?city .
  FILTER(?city a pv:City ; pv:country "US") .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  ?service a pv:Service ;
           pv:appliesToBOM ?bom .
  ?bom pv:containsPart ?part .
  ?part pv:sourcedFrom "Russia" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplierName ?country ?price WHERE {
  ?item a pv:HardwareItem ;
         pv:suppliedBy ?supplier .
  ?supplier rdfs:label ?supplierName ;
             pv:locatedIn ?country .
  ?item pv:cost ?price .
} ORDER BY DESC(?price) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?product ?compatibleProduct (?priceDifference AS ?result) WHERE {
  ?product a pv:Product ;
           pv:compatibleWith ?compatibleProduct .
  ?product pv:price ?productPrice ;
            prodi:hasPriceHistory ?history .
  FILTER (EXISTS { ?history prodi:hasPrice ?price ; prodi:validFrom ?from . })
  BIND ((?productPrice - ?price) AS ?priceDifference)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?email ?phone ?department ?directReport WHERE {
  ?employee a pv:Employee ;
             rdfs:label ?name ;
             pv:hasEmail ?email ;
             pv:hasPhoneNumber ?phone ;
             pv:worksIn ?department ;
             pv:reportsTo ?manager .
  OPTIONAL { ?manager pv:reportsTo ?directReport }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result (AVG(?unitCost) AS ?averageUnitCost) WHERE {
  ?bom a pv:BillOfMaterials ;
       pv:containsHardwarePart ?part .
  ?part a pv:HardwarePart ;
         pv:unitCost ?unitCost .
} GROUP BY ?bom ORDER BY DESC(?averageUnitCost) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?bom WHERE {
  ?bom a pv:BOM ;
        pv:containsPart ?part .
  ?part pv:supplier prodi:supplier-polish .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  ?employee a pv:Employee ;
             pv:areaOfExpertise pv:prod-cat-Sensor .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?encoder (MIN(?priceAmount) AS ?cheapestPrice) WHERE {
  ?encoder a pv:Hardware ; pv:name "Encoder" .
  ?encoder pv:hasSupplier ?supplier .
  ?supplier pv:country ?country .
  ?encoder pv:price ?price .
  ?price pv:amount ?priceAmount ;
           pv:currency "EUR" .
  FILTER(?country = "France" || ?country = "Germany")
} GROUP BY ?encoder ORDER BY ?cheapestPrice LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result WHERE {
  ?service a pv:Service ;
           pv:price ?price .
  ?price pv:amount ?amount ;
         pv:currency "EUR" .
  ?employee a pv:Employee ;
             pv:hasProductManager ?service .
  ORDER BY DESC(?amount)
  LIMIT 1
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  pv:U990-LCD-Inductor pv:compatibleProduct ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?city WHERE {
  ?supplier a pv:Supplier ; pv:country "United States" ;
             pv:hasProduct ?product ;
             pv:addressLocality ?city .
  ?product a pv:Hardware ; pv:name "LCD".
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?supplierName ?country ?priceAmount WHERE {
  ?product a pv:Hardware ;
           pv:price ?price .
  ?price pv:amount ?priceAmount ;
          pv:currency "EUR" .
  ?product pv:hasSupplier ?supplier .
  ?supplier pv:name ?supplierName ;
             pv:country ?country .
} ORDER BY DESC(?priceAmount) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?category ?lightest ?heaviest WHERE {
  ?product a pv:Hardware ; pv:hasCategory ?category .
  OPTIONAL { ?product pv:weight_g ?weight . }
  BIND (MIN(?weight) AS ?lightest)
  BIND (MAX(?weight) AS ?heaviest)
} GROUP BY ?category

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?product ?compatibleProduct (ABS(?price1 - ?price2) AS ?priceDifference) WHERE {
  ?product a pv:Product ;
            pv:compatibleProduct ?compatibleProduct ;
            pv:price ?price1 .
  ?compatibleProduct pv:price ?price2 .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?name ?email ?phone ?departmentName ?directReport WHERE {
  ?employee a pv:Employee ;
             pv:name ?name ;
             pv:email ?email ;
             pv:phone ?phone ;
             pv:memberOf ?department .
  ?department a pv:Department ;
               pv:name ?departmentName .
  OPTIONAL { ?employee pv:hasDirectReport ?directReport . }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?bom (AVG(?price) AS ?averageCost) WHERE {
  ?bom a pv:BillOfMaterial ;
        pv:hasBomPart ?part .
  ?part pv:hasPart ?hardware ;
         pv:price ?price .
} GROUP BY ?bom ORDER BY DESC(?averageCost) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?supplier (AVG(?reliabilityIndex) AS ?averageReliability) WHERE {
  ?product a pv:Product ; pv:hasSupplier ?supplier .
  ?part a pv:BomPart ; pv:hasPart ?product ; pv:reliabilityIndex ?reliabilityIndex .
} GROUP BY ?supplier ORDER BY DESC(?averageReliability) LIMIT 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?bom WHERE {
  ?bom a pv:BillOfMaterial ;
        pv:hasBomPart ?part .
  ?part pv:hasSupplier ?supplier ;
         pv:quantity ?quantity .
  FILTER(?quantity > 0)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  ?employee pv:areaOfExpertise <http://ld.company.org/prod-instances/prod-cat-Sensor> .
  ?employee a pv:Employee ;
             pv:name ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?supplier WHERE {
  ?product a pv:Product ; pv:hasCategory <http://ld.company.org/prod-instances/prod-cat-Compensator> .
  ?product pv:hasSupplier ?supplier .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result WHERE {
  ?service a pv:Service ;
           pv:price ?price .
  ?price pv:amount ?amount ;
         pv:currency "EUR" .
  ?employee a pv:Employee ;
             pv:hasProductManager ?product .
  ?product pv:eligibleFor ?service .
  FILTER(?amount = (SELECT MAX(?maxAmount) WHERE {
    ?service2 a pv:Service ;
               pv:price ?price2 .
    ?price2 pv:amount ?maxAmount ;
             pv:currency "EUR" .
  }))
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  <http://ld.company.org/prod-instances/hw-U990-5234138> pv:compatibleProduct ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?city WHERE {
  ?supplier a pv:Supplier ; pv:country "United States" ;
             pv:hasProduct ?product ;
             pv:supplyFor ?category .
  ?product pv:hasCategory ?category ;
           pv:id "LCDs" .
  ?address pv:addressCountryCode "US" ;
            pv:addressLocality ?city .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?supplierName ?country ?priceAmount WHERE {
  ?product a pv:Hardware ;
           pv:price ?price .
  ?price pv:amount ?priceAmount ;
          pv:currency "EUR" .
  ?product pv:hasSupplier ?supplier .
  ?supplier pv:name ?supplierName ;
             pv:country ?country .
} ORDER BY DESC(?priceAmount) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?category (MIN(?weight_g) AS ?lightest) (MAX(?weight_g) AS ?heaviest) WHERE {
  ?product a pv:Hardware ; pv:hasCategory ?category ; pv:weight_g ?weight_g .
} GROUP BY ?category ORDER BY ?category

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?product ?compatibleProduct (?priceDifference AS ?result) WHERE {
  ?product a pv:Product ;
           pv:compatibleProduct ?compatibleProduct ;
           pv:price ?price .
  ?compatibleProduct pv:price ?compatiblePrice .
  BIND((?price - ?compatiblePrice) AS ?priceDifference)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?name ?email ?phone ?departmentName ?directReportName WHERE {
  ?employee a pv:Employee ;
             pv:name ?name ;
             pv:email ?email ;
             pv:phone ?phone ;
             pv:memberOf ?department ;
             pv:hasDirectReport ?directReport .
  ?department a pv:Department ;
               pv:name ?departmentName .
  OPTIONAL { ?directReport pv:name ?directReportName }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
