PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?bom WHERE {
  ?bom a pv:BillOfMaterial ;
        pv:hasBomPart ?part .
  ?part pv:hasSupplier ?supplier ;
         pv:country "Poland" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  ?employee pv:areaOfExpertise <http://ld.company.org/prod-instances/prod-cat-Sensor> .
