SELECT ?supplier (AVG(?reliabilityIndex) AS ?averageReliability) WHERE {
  ?product a pv:Product ; pv:hasSupplier ?supplier .
  ?part a pv:BomPart ; pv:hasPart ?product ; pv:reliabilityIndex ?reliabilityIndex .
} GROUP BY ?supplier ORDER BY DESC(?averageReliability) LIMIT 5

